  s4_active_stream_label: { en: 'Active Care Stream:', hi: 'सक्रिय चिकित्सा पद्धति:', sa: 'सक्रिय-चिकित्सा-पद्धतिः:', mr: 'सक्रिय उपचार पद्धती:', ta: 'செயலில் உள்ள சிகிச்சை முறை:', te: 'యాక్టివ్ చికిత్సా విధానం:', bn: 'সক্রিয় চিকিৎসা পদ্ধতি:', gu: 'સક્રિય સારવાર પદ્ધતિ:', kn: 'ಸಕ್ರಿಯ ಚಿಕಿತ್ಸಾ ವಿಧಾನ:', ml: 'സജീവ ചികിത്സാ രീതി:' },
  s4_continue_btn: { en: 'Continue to Language Selection', hi: 'भाषा चयन हेतु आगे बढ़ें', sa: 'भाषा-चयनार्थम् अग्रे गच्छतु', mr: 'भाषा निवडीसाठी पुढे जा', ta: 'மொழி தேர்வுக்கு தொடரவும்', te: 'భాష ఎంపికకు కొనసాగండి', bn: 'ভাষা নির্বাচনে এগিয়ে যান', gu: 'ભાષા પસંદગી માટે આગળ વધો', kn: 'ಭಾಷಾ ಆಯ್ಕೆಗೆ ಮುಂದುವರಿಸಿ', ml: 'ഭാഷാ തിരഞ്ഞെടുപ്പിലേക്ക് തുടരുക' },

