  s5_badge: { en: 'Step 5 of 9', hi: 'चरण 5 / 9', sa: 'सोपानम् ५/९', mr: 'पायरी ५ / ९', ta: 'படி 5 / 9', te: 'దశ 5 / 9', bn: 'ধাপ ৫ / ৯', gu: 'પગલું 5 / 9', kn: 'ಹಂತ 5 / 9', ml: 'ഘട്ടം 5 / 9' },
  s5_title: { en: 'Select Preferred Language for AI Intake', hi: 'एआई जांच हेतु पसंदीदा भाषा चुनें', sa: 'एआई-ग्रहणार्थं वाञ्छित-भाषां चिनुत', mr: 'एआय इनटेकसाठी पसंतीची भाषा निवडा', ta: 'AI உள்வாங்குதலுக்கான விருப்பமான மொழியைத் தேர்ந்தெடுக்கவும்', te: 'AI ఇన్‌టేక్ కోసం ఇష్టమైన భాషను ఎంచుకోండి', bn: 'এআই ইনটেকের জন্য পছন্দের ভাষা নির্বাচন করুন', gu: 'AI ઇનટેક માટે પસંદગીની ભાષા પસંદ કરો', kn: 'AI ಇನ್‌ಟೇಕ್‌ಗಾಗಿ ಆದ್ಯತೆಯ ಭಾಷೆಯನ್ನು ಆಯ್ಕೆಮಾಡಿ', ml: 'AI ഇൻടേക്കിനുള്ള ഇഷ്ട ഭാഷ തിരഞ്ഞെടുക്കുക' },
  s5_subtitle: { en: 'AyuFlow speaks and understands 10+ Indian regional languages and classical Ayurvedic terminology.', hi: 'आयुफ्लो 10+ भारतीय क्षेत्रीय भाषाओं और शास्त्रीय आयुर्वेदिक शब्दावली को समझता एवं बोलता है।', sa: 'आयुफ्लो-सॉफ्टवेयरं दशाधिक-भारतीय-प्रादेशिक-भाषाः शास्त्रीय-आयुर्वेद-शब्दावलीं च जानाति वदति च।', mr: 'आयुफ्लो 10+ भारतीय प्रादेशिक भाषा आणि शास्त्रीय आयुर्वेदिक शब्दावली बोलतो आणि समजतो.', ta: 'AyuFlow 10+ இந்திய பிராந்திய மொழிகள் மற்றும் பாரம்பரிய ஆயுர்வேத சொற்களைப் புரிந்துகொண்டு பேசுகிறது.', te: 'AyuFlow 10+ భారతీయ ప్రాంతీయ భాషలు మరియు సాంప్రదాయ ఆయుర్వేద పరిభాషను మాట్లాడుతుంది మరియు అర్థం చేసుకుంటుంది.', bn: 'আয়ুফ্লো ১০+ ভারতীয় আঞ্চলিক ভাষা এবং ক্লাসিক্যাল আয়ুর্বেদিক পরিভাষা বোঝে ও বলে।', gu: 'AyuFlow 10+ ભારતીય પ્રાદેશિક ભાષાઓ અને ક્લાસિકલ આયુર્વેદિક પરિભાષા બોલે છે અને સમજે છે.', kn: 'ಆಯುಫ್ಲೋ 10+ ಭಾರತೀಯ ಪ್ರಾದೇಶಿಕ ಭಾಷೆಗಳು ಮತ್ತು ಶಾಸ್ತ್ರೀಯ ಆಯುರ್ವೇದ ಪರಿಭಾಷೆಯನ್ನು ಮಾತನಾಡುತ್ತದೆ ಮತ್ತು ಅರ್ಥಮಾಡಿಕೊಳ್ಳುತ್ತದೆ.', ml: 'ആയുഫ്ലോ 10+ ഇന്ത്യൻ പ്രാദേശിക ഭാഷകളും ക്ലാസിക്കൽ ആയുർവേദ പദാവലിയും സംസാരിക്കുകയും മനസ്സിലാക്കുകയും ചെയ്യുന്നു.' },
  s5_back_btn: { en: 'Back to Care Stream', hi: 'चिकित्सा पद्धति पर वापस जाएं', sa: 'चिकित्सा-पद्धति-प्रति प्रत्यागच्छतु', mr: 'उपचार पद्धतीकडे परत जा', ta: 'சிகிச்சை முறைக்குத் திரும்பு', te: 'చికిత్సా విధానానికి తిరిగి వెళ్ళండి', bn: 'চিকিৎসা পদ্ধতিতে ফিরে যান', gu: 'સારવાર પદ્ધતિ પર પાછા જાઓ', kn: 'ಚಿಕಿತ್ಸಾ ವಿಧಾನಕ್ಕೆ ಹಿಂತಿರುಗಿ', ml: 'ചികിത്സാ രീതിയിലേക്ക് മടങ്ങുക' },
