  s9_summary_stream: { en: 'Care Stream:', hi: 'चिकित्सा पद्धति:', sa: 'चिकित्सा-पद्धतिः:', mr: 'उपचार पद्धती:', ta: 'சிகிச்சை முறை:', te: 'చికిత్సా విధానం:', bn: 'চিকিৎসা পদ্ধতি:', gu: 'સારવાર પદ્ધતિ:', kn: 'ಚಿಕಿತ್ಸಾ ವಿಧಾನ:', ml: 'ചികിത്സാ രീതി:' },
