  s9_not_answered: { en: 'Not answered', hi: 'उत्तर नहीं दिया', sa: 'अनुत्तरम्', mr: 'उत्तर दिलेले नाही', ta: 'பதிலளிக்கப்படவில்லை', te: 'సమాధానం ఇవ్వలేదు', bn: 'উত্তর দেওয়া হয়নি', gu: 'જવાબ આપ્યો નથી', kn: 'ಉತ್ತರಿಸಿಲ್ಲ', ml: 'ഉത്തരം നൽകിയിട്ടില്ല' },
