  lp_back_exclaim: { en: 'Back!', hi: 'वापसी पर!', sa: 'पुनरागमने!', mr: 'परत!', ta: 'மீண்டும்!', te: 'తిరిగి!', bn: 'ফিরে!', gu: 'પાછા!', kn: 'ಮತ್ತೆ!', ml: 'തിരികെ!' },
  lp_subtitle_patient: { en: 'Sign in with your ABHA Number, Mobile, or Token ID.', hi: 'अपने आभा नंबर, मोबाइल या टोकन आईडी से साइन इन करें।', sa: 'स्व-आभा-सङ्ख्यया चलदूरभाषेण टोकन-परिचयेन वा प्रविशतु।', mr: 'तुमच्या आभा क्रमांक, मोबाईल किंवा टोकन आयडीने साइन इन करा.', ta: 'உங்கள் ABHA எண், மொபைல் அல்லது டோக்கன் ஐடி மூலம் உள்நுழையவும்.', te: 'మీ ABHA నంబర్, మొబైల్ లేదా టోకెన్ ఐడీతో సైన్ ఇన్ చేయండి.', bn: 'আপনার ABHA নম্বর, মোবাইল বা টোকেন আইডি দিয়ে সাইন ইন করুন।', gu: 'તમારા ABHA નંબર, મોબાઇલ અથવા ટોકન આઈડીથી સાઇન ઇન કરો.', kn: 'ನಿಮ್ಮ ABHA ಸಂಖ್ಯೆ, ಮೊಬೈಲ್ ಅಥವಾ ಟೋಕನ್ ಐಡಿಯೊಂದಿಗೆ ಸೈನ್ ಇನ್ ಮಾಡಿ.', ml: 'നിങ്ങളുടെ ABHA നമ്പർ, മൊബൈൽ അല്ലെങ്കിൽ ടോക്കൺ ഐഡി ഉപയോഗിച്ച് സൈൻ ഇൻ ചെയ്യുക.' },
  lp_subtitle_doctor: { en: 'This is a demo sign-in — no credentials are actually verified.', hi: 'यह एक डेमो साइन-इन है — कोई भी क्रेडेंशियल वास्तव में सत्यापित नहीं किया जाता।', sa: 'इदं प्रदर्शन-प्रवेशः अस्ति — कोऽपि प्रमाणपत्रं वास्तवतः सत्यापितं न भवति।', mr: 'हे डेमो साइन-इन आहे — कोणतीही क्रेडेन्शियल्स प्रत्यक्षात सत्यापित केली जात नाहीत.', ta: 'இது ஒரு டெமோ உள்நுழைவு — எந்த சான்றுகளும் உண்மையில் சரிபார்க்கப்படுவதில்லை.', te: 'ఇది డెమో సైన్-ఇన్ — ఏ ఆధారాలు వాస్తవంగా ధృవీకరించబడవు.', bn: 'এটি একটি ডেমো সাইন-ইন — কোনো পরিচয়পত্র বাস্তবে যাচাই করা হয় না।', gu: 'આ ડેમો સાઇન-ઇન છે — કોઈ પણ ઓળખપત્ર વાસ્તવમાં ચકાસવામાં આવતું નથી.', kn: 'ಇದು ಡೆಮೊ ಸೈನ್-ಇನ್ — ಯಾವುದೇ ರುಜುವಾತುಗಳನ್ನು ನಿಜವಾಗಿ ಪರಿಶೀಲಿಸಲಾಗುವುದಿಲ್ಲ.', ml: 'ഇത് ഒരു ഡെമോ സൈൻ-ഇൻ ആണ് — ഒരു ക്രെഡൻഷ്യലും യഥാർത്ഥത്തിൽ പരിശോധിക്കുന്നില്ല.' },
  lp_subtitle_staff: { en: 'Sign in with your institutional credentials.', hi: 'अपने संस्थागत क्रेडेंशियल से साइन इन करें।', sa: 'स्व-संस्था-प्रमाणपत्रेण प्रविशतु।', mr: 'तुमच्या संस्थात्मक क्रेडेन्शियल्सने साइन इन करा.', ta: 'உங்கள் நிறுவன சான்றுகளுடன் உள்நுழையவும்.', te: 'మీ సంస్థాగత ఆధారాలతో సైన్ ఇన్ చేయండి.', bn: 'আপনার প্রাতিষ্ঠানিক পরিচয়পত্র দিয়ে সাইন ইন করুন।', gu: 'તમારા સંસ્થાકીય ઓળખપત્રોથી સાઇન ઇન કરો.', kn: 'ನಿಮ್ಮ ಸಾಂಸ್ಥಿಕ ರುಜುವಾತುಗಳೊಂದಿಗೆ ಸೈನ್ ಇನ್ ಮಾಡಿ.', ml: 'നിങ്ങളുടെ സ്ഥാപന ക്രെഡൻഷ്യലുകൾ ഉപയോഗിച്ച് സൈൻ ഇൻ ചെയ്യുക.' },
  lp_signing_in_as: { en: 'Signing in as', hi: 'इस रूप में साइन इन कर रहे हैं:', sa: 'इति प्रविशति:', mr: 'याप्रमाणे साइन इन करत आहात:', ta: 'இதுவாக உள்நுழைகிறீர்கள்:', te: 'దీనిగా సైన్ ఇన్ అవుతున్నారు:', bn: 'এই হিসেবে সাইন ইন করছেন:', gu: 'આ રીતે સાઇન ઇન કરી રહ્યા છો:', kn: 'ಹೀಗೆ ಸೈನ್ ಇನ್ ಆಗುತ್ತಿದ್ದೀರಿ:', ml: 'ഇതായി സൈൻ ഇൻ ചെയ്യുന്നു:' },
