  wp_blood_group: { en: 'Blood Group', hi: 'ब्लड ग्रुप', sa: 'रक्त-वर्गः', mr: 'रक्तगट', ta: 'இரத்த வகை', te: 'రక్త వర్గం', bn: 'রক্তের গ্রুপ', gu: 'બ્લડ ગ્રુપ', kn: 'ರಕ್ತದ ಗುಂಪು', ml: 'ബ്ലഡ് ഗ്രൂപ്പ്' },
  wp_address: { en: 'Residential Area / City', hi: 'निवास क्षेत्र / शहर', sa: 'निवास-क्षेत्रम् / नगरम्', mr: 'निवासी क्षेत्र / शहर', ta: 'குடியிருப்பு பகுதி / நகரம்', te: 'నివాస ప్రాంతం / నగరం', bn: 'আবাসিক এলাকা / শহর', gu: 'રહેણાંક વિસ્તાર / શહેર', kn: 'ವಸತಿ ಪ್ರದೇಶ / ನಗರ', ml: 'താമസ പ്രദേശം / നഗരം' },
