  lab_attached_docs: { en: 'Attached Docs:', hi: 'संलग्न दस्तावेज़:', sa: 'योजित-दस्तावेजाः:', mr: 'जोडलेले दस्तऐवज:', ta: 'இணைக்கப்பட்ட ஆவணங்கள்:', te: 'జోడించిన పత్రాలు:', bn: 'সংযুক্ত নথি:', gu: 'જોડાયેલા દસ્તાવેજો:', kn: 'ಲಗತ್ತಿಸಿದ ದಾಖಲೆಗಳು:', ml: 'ചേർത്ത രേഖകൾ:' },
  lab_upload_link: { en: 'Upload & Link Diagnostic Report', hi: 'डायग्नोस्टिक रिपोर्ट अपलोड और लिंक करें', sa: 'निदान-प्रतिवेदनं प्रेषयतु योजयतु च', mr: 'डायग्नोस्टिक रिपोर्ट अपलोड आणि लिंक करा', ta: 'நோயறிதல் அறிக்கையை பதிவேற்றி இணைக்கவும்', te: 'డయాగ్నస్టిక్ రిపోర్ట్‌ను అప్‌లోడ్ చేసి లింక్ చేయండి', bn: 'ডায়াগনস্টিক রিপোর্ট আপলোড ও লিঙ্ক করুন', gu: 'ડાયગ્નોસ્ટિક રિપોર્ટ અપલોડ અને લિંક કરો', kn: 'ಡಯಾಗ್ನೋಸ್ಟಿಕ್ ವರದಿಯನ್ನು ಅಪ್‌ಲೋಡ್ ಮಾಡಿ ಲಿಂಕ್ ಮಾಡಿ', ml: 'ഡയഗ്നോസ്റ്റിക് റിപ്പോർട്ട് അപ്‌ലോഡ് ചെയ്ത് ലിങ്ക് ചെയ്യുക' },
  lab_attach_report: { en: 'Attach Diagnostic Report', hi: 'डायग्नोस्टिक रिपोर्ट संलग्न करें', sa: 'निदान-प्रतिवेदनं योजयतु', mr: 'डायग्नोस्टिक रिपोर्ट संलग्न करा', ta: 'நோயறிதல் அறிக்கையை இணைக்கவும்', te: 'డయాగ్నస్టిక్ రిపోర్ట్‌ను జోడించండి', bn: 'ডায়াগনস্টিক রিপোর্ট সংযুক্ত করুন', gu: 'ડાયગ્નોસ્ટિક રિપોર્ટ જોડો', kn: 'ಡಯಾಗ್ನೋಸ್ಟಿಕ್ ವರದಿಯನ್ನು ಲಗತ್ತಿಸಿ', ml: 'ഡയഗ്നോസ്റ്റിക് റിപ്പോർട്ട് ചേർക്കുക' },
