export const getTranslation = (
  key: string,
  lang: string = 'en',
  vars?: Record<string, string | number>
): string => {
  const normLang = (SUPPORTED_LANGUAGES.includes(lang as LanguageCode) ? lang : 'en') as LanguageCode;
  let str = TRANSLATIONS[key]?.[normLang] || TRANSLATIONS[key]?.en || key;
  if (vars) {
    Object.entries(vars).forEach(([k, v]) => {
      str = str.replace(new RegExp(`\\{${k}\\}`, 'g'), String(v));
    });
  }
  return str;
};

/** Hook: reads the active patient language from context automatically, so callers
 * just do `const { t } = useTranslation(); t('some_key', { n: 3 })` instead of
 * threading a language code through every component by hand. */
export const useTranslation = () => {
  const { patientLanguage } = useApp();
  const t = (key: string, vars?: Record<string, string | number>): string =>
    getTranslation(key, patientLanguage, vars);
  return { t, lang: patientLanguage as LanguageCode };
};
